mapper.select:
 SELECT
		DISTINCT t.id,t.title,t.priority,t.due_date AS
		dueDate,c.category,t.content FROM todo AS t JOIN category AS c on
		t.category_id = c.id LEFT JOIN user_todo AS ut ON t.id = ut.todo_id LEFT
		JOIN users AS u ON ut.user_id = u.id 


				AND t.id = #{id}



				AND t.title ILIKE '%' || #{title} || '%'



				AND t.priority = #{priority}



				AND t.due_date >= #{dueDateFrom}



				AND t.due_date <= #{dueDateTo}



				AND t.category_id = #{categoryId}



				AND t.content ILIKE '%' || #{content} || '%'



				AND ut.user_id = #{userId}



				AND u.name ILIKE '%' || #{name} || '%'
			 AND t.deleted
		!= true  ORDER BY id ASC

mapper.update:
UPDATE todo SET
deleted_at = #{deletedAt},deleted_by = #{deletedBy},deleted = #{deleted}
Where id = #{id}
